window.__LOCAL_TEMPLATES = {
  "home": "<div class=\"hero\">\n  <div class=\"hero-bg\"></div>\n\n  <div class=\"hero-left\">\n    <div class=\"hero-eyebrow reveal\">NextChapter &middot; 90-Day Jump-Start Program</div>\n    <h1 class=\"hero-headline reveal\">90 Days to an AI <em>Innovation Pipeline</em></h1>\n    <p class=\"hero-sub reveal\">\n      AI adoption without structure is theatre. This framework turns the aspiration into an operating discipline —\n      from honest diagnosis through portfolio governance. The 90 days are the ignition.\n      <strong>The engine runs forever.</strong>\n    </p>\n    <div class=\"hero-btns reveal\">\n      <button class=\"btn-gold\"  data-nav=\"pipeline\">Start the Pipeline</button>\n      <button class=\"btn-ghost\" data-nav=\"learn\">Read the Research</button>\n    </div>\n    <div class=\"section-label reveal\" style=\"margin-bottom:0\">The 90-Day Plan</div>\n    <div class=\"u-6d56738\" style=\"margin-top:-12px\">\n      <div class=\"reveal u-65536d3\">\n        <div class=\"u-3499ee4\">01</div>\n        <div>\n          <div class=\"u-7cbaf57\">Diagnose</div>\n          <div class=\"t-stone-13\">Assess readiness, surface ideas, build the Blue Sky Portfolio.</div>\n        </div>\n      </div>\n      <div class=\"reveal u-65536d3\">\n        <div class=\"u-3499ee4\">02</div>\n        <div>\n          <div class=\"u-7cbaf57\">Organize</div>\n          <div class=\"t-stone-13\">Assign ownership, realign incentives, establish rhythm.</div>\n        </div>\n      </div>\n      <div class=\"reveal u-65536d3\">\n        <div class=\"u-3499ee4\">03</div>\n        <div>\n          <div class=\"u-7cbaf57\">Prepare</div>\n          <div class=\"t-stone-13\">Structure portfolio, allocate capital, design experiments.</div>\n        </div>\n      </div>\n      <div class=\"reveal u-65536d3\">\n        <div class=\"u-3499ee4\">04</div>\n        <div>\n          <div class=\"u-7cbaf57\">Ignite</div>\n          <div class=\"t-stone-13\">Launch experiments, establish governance, first review.</div>\n        </div>\n      </div>\n      <div class=\"reveal u-65536d3\">\n        <div class=\"u-3499ee4\">05</div>\n        <div>\n          <div class=\"u-7cbaf57\">Navigate</div>\n          <div class=\"t-stone-13\">Ongoing: manage the live pipeline with Buy/Sell/Hold discipline.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"hero-right\">\n    <div class=\"hero-intro-video overview-video-card reveal\">\n      <div class=\"overview-video-row\">\n        <div class=\"overview-video-cell\">\n          <div class=\"overview-video-label\">Program Introduction</div>\n          <video class=\"overview-video\" controls preload=\"auto\" playsinline><source src=\"assets/media/innov-program-intro.mp4\" type=\"video/mp4\">Your browser does not support embedded video.</video>\n        </div>\n        <div class=\"overview-video-cell\">\n          <div class=\"overview-video-label\">Convergence Podcast: AI Innovation Pipeline in 90 Days</div>\n          <video class=\"overview-video\" controls preload=\"auto\" playsinline poster=\"assets/media/convergence-poster.jpg\"><source src=\"assets/media/innov-convergence-podcast.mp4\" type=\"video/mp4\">Your browser does not support embedded video.</video>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- Scrolling marquee strip -->\n<div class=\"marquee-wrap\">\n  <div class=\"marquee-track\">\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Diagnose</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Organize</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Prepare</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Ignite</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Navigate</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>AI Portfolio Strategy</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Stage-Gate Discipline</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Buy · Sell · Hold</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>90-Day Transformation</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Innovation Governance</span>\n    <!-- duplicate set for seamless scroll -->\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Diagnose</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Organize</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Prepare</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Ignite</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Navigate</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>AI Portfolio Strategy</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Stage-Gate Discipline</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Buy · Sell · Hold</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>90-Day Transformation</span>\n    <span class=\"marquee-item\"><span class=\"marquee-dot\"></span>Innovation Governance</span>\n  </div>\n</div>\n\n<!-- \"Why This Matters\" + entry cards -->\n<div class=\"u-e9251e6\">\n  <div class=\"wrap\">\n    <div class=\"grid-2 u-e1989f2\">\n\n      <div>\n        <div class=\"section-label reveal\">Why This Matters</div>\n        <div class=\"pullquote reveal\">\n          Most organizations don't fail at AI because of technology. They fail because they treat AI initiatives as\n          individual projects rather than a managed innovation portfolio.\n          <cite>— Faisal Hoque, Fast Company</cite>\n        </div>\n      </div>\n\n      <div class=\"grid-2 u-7e08abf\">\n        <div class=\"card card-link reveal u-8076619\" data-nav=\"learn\">\n          <div class=\"u-47623be\">Learn</div>\n          <div class=\"u-a80bcd3\">Articles, books, and research behind every framework in this pipeline.</div>\n          <div class=\"card-arrow\">Explore Library</div>\n        </div>\n\n        <div class=\"card card-link reveal u-8076619\" data-nav=\"pipeline\">\n          <div class=\"u-47623be\">Pipeline</div>\n          <div class=\"u-a80bcd3\">The full 90-day journey — step by step, phase by phase.</div>\n          <div class=\"card-arrow\">Begin Now</div>\n        </div>\n\n        <div class=\"card card-link reveal u-8076619\" data-nav=\"phase5\">\n          <div class=\"u-47623be\">Navigate</div>\n          <div class=\"u-a80bcd3\">Ongoing dashboard once your pipeline is operational.</div>\n          <div class=\"card-arrow\">Open Dashboard</div>\n        </div>\n\n        <div class=\"card card-link reveal u-8076619\" data-url=\"https://faisalhoque.com\">\n          <div class=\"u-47623be\">From the Author</div>\n          <div class=\"u-a80bcd3\">faisalhoque.com — writing, speaking, and advisory work.</div>\n          <div class=\"card-arrow\">Visit Site</div>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n",
  "learn": "<div class=\"pt-100\">\n  <div class=\"wrap u-91c9940\">\n    <div class=\"section-label reveal\">Research &amp; Reading</div>\n    <div class=\"section-title insights-section-title reveal\">Foundation <em>Reading</em></div>\n    <p class=\"section-body reveal mb-12\">Every step in the 90-day pipeline is grounded in published research. Start with the anchor articles linked below. You'll find further reading relevant to each step available to you in the module.</p>\n\n    <div class=\"u-53a30b8 u-0e27ba5\">\n      <a href=\"https://faisalhoque.com/heres-how-to-jump-start-your-companys-ai-transformation-in-90-days/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Fast Company</span>\n          <span class=\"insight-date\">The 90-Day Plan</span>\n        </div>\n        <div class=\"insight-title\">How to Jump-Start Your Company's AI Transformation in 90 Days</div>\n        <div class=\"insight-excerpt\">The plan behind this module: four pillars, four phases, and the governance machinery that keeps the pipeline running beyond day 90.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n      <a href=\"https://faisalhoque.com/manage-your-ai-investments-like-a-portfolio/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Harvard Business Review</span>\n          <span class=\"insight-date\">Portfolio Management</span>\n        </div>\n        <div class=\"insight-title\">Manage Your AI Investments Like a Portfolio</div>\n        <div class=\"insight-excerpt\">The step-by-step portfolio methodology: Buy/Sell/Hold scoring, stage gates, and the four portfolio stages that structure the pipeline.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n      <a href=\"https://faisalhoque.com/two-frameworks-for-balancing-ai-innovation-and-risk/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Harvard Business Review</span>\n          <span class=\"insight-date\">Frameworks</span>\n        </div>\n        <div class=\"insight-title\">Two Frameworks for Balancing AI Innovation and Risk</div>\n        <div class=\"insight-excerpt\">Introduces OPEN and CARE, the two complementary frameworks for harnessing AI's potential while guarding against its risks.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n      <a href=\"https://faisalhoque.com/how-to-build-an-ai-innovation-pipeline-that-creates-real-long-term-value/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Fast Company</span>\n          <span class=\"insight-date\">Playbook</span>\n        </div>\n        <div class=\"insight-title\">How to Build an AI Innovation Pipeline That Creates Real Long-Term Value</div>\n        <div class=\"insight-excerpt\">The pipeline playbook in practice, following a midsize manufacturer from baseline assessment to operational deployment.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n      <a href=\"https://faisalhoque.com/why-your-organization-needs-both-ai-moonshots-and-mundane-wins/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Fast Company</span>\n          <span class=\"insight-date\">Portfolio Balance</span>\n        </div>\n        <div class=\"insight-title\">Why Your Organization Needs Both AI Moonshots and Mundane Wins</div>\n        <div class=\"insight-excerpt\">Why a balanced mix of transformative bets and reliable quick wins beats going all in on either.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n      <a href=\"https://faisalhoque.com/real-enterprise-transformation-with-ai-requires-six-foundations-not-one-heres-how-to-build-them-all/\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Fast Company</span>\n          <span class=\"insight-date\">Series Overview</span>\n        </div>\n        <div class=\"insight-title\">Real Enterprise Transformation With AI Requires Six Foundations, Not One</div>\n        <div class=\"insight-excerpt\">Where the pipeline fits in the wider transformation: six 90-day plans spanning governance, architecture, leadership, culture, and workforce.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">Read &rarr;</span></div>\n      </a>\n    </div>\n\n    <div class=\"section-label reveal\">Books</div>\n    <div class=\"section-title insights-section-title reveal mb-10\">Deeper <em>Reading</em></div>\n    <div class=\"u-53a30b8\">\n      <a href=\"https://www.amazon.com/dp/B0DGF7T8QG\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Book</span>\n          <span class=\"insight-date\">Faisal Hoque</span>\n        </div>\n        <div class=\"insight-title\">TRANSCEND</div>\n        <div class=\"insight-excerpt\">USA Today and LA Times bestseller. The OPEN and CARE frameworks in full, with the thinking behind them.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">View on Amazon &rarr;</span></div>\n      </a>\n      <a href=\"https://www.amazon.com/Reimagining-Government-Achieving-Promise-AI/dp/B0FLDZHCR5\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Book</span>\n          <span class=\"insight-date\">Hoque, Nelson &amp; Davenport</span>\n        </div>\n        <div class=\"insight-title\">Reimagining Government</div>\n        <div class=\"insight-excerpt\">AI transformation for the public sector. Develops the step-by-step portfolio management approach in depth.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">View on Amazon &rarr;</span></div>\n      </a>\n      <a href=\"https://www.amazon.com/dp/B0BWSD8HPK\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Book</span>\n          <span class=\"insight-date\">Faisal Hoque</span>\n        </div>\n        <div class=\"insight-title\">REINVENT</div>\n        <div class=\"insight-excerpt\">#1 Wall Street Journal bestseller, published in association with IMD. How organizations navigate continuous business transformation in a hyperdigital era.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">View on Amazon &rarr;</span></div>\n      </a>\n      <a href=\"https://www.amazon.com/dp/1639080201\" target=\"_blank\" rel=\"noopener\" class=\"insight-card reveal\">\n        <div class=\"insight-card-header\">\n          <span class=\"insight-badge insight-badge--mono\">Book</span>\n          <span class=\"insight-date\">Faisal Hoque</span>\n        </div>\n        <div class=\"insight-title\">Everything Connects</div>\n        <div class=\"insight-excerpt\">#2 Wall Street Journal and USA Today bestseller. Cultivating mindfulness, creativity, and innovation as the foundations of long-term value.</div>\n        <div class=\"insight-card-foot\"><span class=\"insight-cta\">View on Amazon &rarr;</span></div>\n      </a>\n    </div>\n\n  </div>\n</div>\n",
  "insights": "<!-- ─────────────────────────────────────────────────────────────\n     insights.html — Insights screen (skeleton; hydrated by insights.js)\n     The hero, the three section headings and the tab bar are static.\n     The card lists (Latest Thoughts, Conversations, Worth Your Time)\n     are data-driven and filled into the [data-slot] containers by\n     js/insights.js from its data arrays. Tab clicks scroll to a\n     section (delegated on [data-insights-tabs]); no inline JS.\n     ───────────────────────────────────────────────────────────── -->\n<div class=\"u-70c6b34\">\n\n  <div class=\"u-4f90335\">\n    <div class=\"section-label\">Insights</div>\n    <div class=\"u-3536245\">\n      <div>\n        <h1 class=\"section-title u-d51702b\">Ideas &amp; <em>Conversations</em></h1>\n        <p class=\"u-7e59c65\">Faisal Hoque&rsquo;s latest writing across six outlets, the CONVERGENCE podcast and interview appearances, and a shelf of work by people we admire.</p>\n      </div>\n    </div>\n\n    <div class=\"u-58a9696\" data-insights-tabs>\n      <button type=\"button\" class=\"insight-filter\" data-itab=\"latest\">Latest Thoughts</button>\n      <button type=\"button\" class=\"insight-filter\" data-itab=\"conversations\">Conversations</button>\n      <button type=\"button\" class=\"insight-filter\" data-itab=\"worth\">Worth Your Time</button>\n    </div>\n  </div>\n\n  <div class=\"u-dc4836c\">\n    <div id=\"insights-latest\" class=\"insights-section\">\n      <div class=\"section-title insights-section-title\">Latest <em>Thoughts</em></div>\n      <div data-slot=\"latest\"></div>\n    </div>\n    <div id=\"insights-conversations\" class=\"insights-section\" style=\"margin-top:56px\">\n      <div class=\"section-title insights-section-title\">Conversations</div>\n      <div data-slot=\"conversations\"></div>\n    </div>\n    <div id=\"insights-worth\" class=\"insights-section\" style=\"margin-top:56px\">\n      <div class=\"section-title insights-section-title\">Worth Your <em>Time</em></div>\n      <div data-slot=\"worth\"></div>\n    </div>\n  </div>\n\n</div>\n",
  "login": "<!-- ─────────────────────────────────────────────────────────────\n     login.html — Sign-in screen (markup only; no inline JS)\n     Served at /apps/{role}/{module}/login — every program has its own\n     door, so this screen already knows which program and which role\n     space it is the entrance to. Hydrated by auth.js →\n     Entry.mount('login', …). Dynamic bits (field values, errors, busy\n     state and focus) are filled in JS.\n     data-go   → switch entry step        data-field → validation key\n     data-err  → error slot for a field   data-submit → submit button\n     ───────────────────────────────────────────────────────────── -->\n<div class=\"login-screen\"><div class=\"login-card\">\n  <div class=\"login-eyebrow\" data-slot=\"module-name\">AI Innovation Pipeline</div>\n  <h1 class=\"login-title\">Sign <em>in</em></h1>\n  <p class=\"login-sub\" data-slot=\"sub\">Enter your username and password to open your organization's workspace.</p>\n\n  <!-- The account this device signed in as last, offered rather than assumed.\n       Filled in and unhidden by auth.js (hydrateLogin) only when there is one;\n       clicking it restores that session, and ignoring it and typing signs in as\n       somebody else. See bootApp in js/app.js for why it is not automatic. -->\n  <div class=\"entry-resume\" data-slot=\"resume\" hidden>\n    <button type=\"button\" class=\"btn-gold login-btn\" data-resume>Continue as <span data-slot=\"resume-name\"></span></button>\n    <p class=\"login-sub entry-resume-sub\">or sign in as someone else</p>\n  </div>\n\n  <form class=\"entry-form\" data-auth=\"login\" novalidate autocomplete=\"off\">\n    <!-- Two fields, for every account. An Organization field used to come\n         first, because a username was only unique inside its own tenant and the\n         server would otherwise have had to search for the name and could find\n         the wrong person. Usernames are unique across the installation again\n         (api/sql/global-unique-login.sql), enforced wherever one can be created\n         or renamed — so the username IS the identity and there is nothing left\n         for that field to disambiguate. See AuthController. -->\n    <input id=\"loginUser\" class=\"entry-text-input\" type=\"text\" autocomplete=\"username\"\n           placeholder=\"Username\" data-field=\"user\" aria-label=\"Username\"/>\n    <div class=\"entry-field-err\" data-err=\"user\" role=\"alert\"></div>\n\n    <!-- A password (Directive 2 Oct 2026, Part 5): checked by the server, never\n         kept by this page. An old PIN still works once and must then be replaced. -->\n    <input id=\"loginPassword\" class=\"entry-text-input\" type=\"password\"\n           autocomplete=\"current-password\" placeholder=\"Password\" data-field=\"password\" aria-label=\"Password\"/>\n    <div class=\"entry-field-err\" data-err=\"password\" role=\"alert\"></div>\n\n    <div class=\"entry-err\" data-err=\"_general\" role=\"alert\" hidden></div>\n\n    <label class=\"entry-remember\">\n      <input type=\"checkbox\" id=\"loginRemember\"/> <span>Remember me on this device</span>\n    </label>\n\n    <button type=\"submit\" class=\"btn-gold login-btn\" data-submit>Sign In &rarr;</button>\n  </form>\n\n  <div class=\"entry-foot\">\n    <!-- Sign-up for THIS program. The label says which kind of account that\n         makes, because the role is no longer a question on the form — it is\n         the address. auth.js rewrites it per role space. -->\n    <button type=\"button\" class=\"entry-foot-btn\" data-go=\"setup\" data-slot=\"signup-link\">Create an account</button>\n    <button type=\"button\" class=\"entry-foot-btn\" data-go=\"admin-login\">Admin</button>\n  </div>\n</div></div>\n",
  "setup": "<!-- ─────────────────────────────────────────────────────────────\n     setup.html — the sign-up screen (markup only)\n     Served at /apps/signup, hydrated by auth.js → Entry.mount('setup', …).\n     The Back button is hidden on first run (no organizations exist yet).\n\n     ONE SIGN-UP FOR ALL TWELVE PROGRAMS. Sign-IN still belongs to a program —\n     /apps/leaders/judgment-critical-thinking/login wears that program's name\n     and colours —\n     but creating an account does not: it decides which of the two audiences\n     you belong to, and that answer then governs every program in that space.\n     So the question is asked here, on the form, rather than inferred from\n     whichever door the visitor happened to arrive at. The twelve old\n     /apps/{role}/{program}/signup addresses 301 here (index.php), and the\n     choice below is what they used to answer silently.\n\n     WHAT EACH ROLE IS ASKED. An Enterprise account is a team, so it names the\n     organization — the label every screen gives the shared workspace. Nobody\n     types it to sign in: that screen takes a username and a password, and the\n     username is unique installation-wide. A Leader account is one person: it\n     has no organization to name, so the field is not shown and the server\n     derives the workspace's name from theirs. Everything else is the same for\n     both, and auth.js shows or hides that one cell as the choice changes.\n\n     WHAT EACH ROLE GETS. Its whole role space — all six programs — either way.\n     An Enterprise organization holds them as a pool for its administrator to\n     assign; a Leader simply holds all six. Nothing here picks programs, because\n     with a shared sign-up there is no address to pick them from and a list of\n     twelve checkboxes is a worse first question than the one above.\n     SetupController::entitlementFor is the authority and ignores anything sent.\n     ───────────────────────────────────────────────────────────── -->\n<div class=\"login-screen entry-wide\">\n  <div class=\"login-card entry-card-wide\">\n    <button type=\"button\" class=\"entry-back\" data-go=\"launchpad\" data-back>&larr; All programs</button>\n    <div class=\"login-eyebrow\" data-slot=\"module-name\">90-Day Programs</div>\n    <h1 class=\"login-title\" data-slot=\"title\">Create your <em>account</em></h1>\n    <p class=\"login-sub\" data-slot=\"sub\">Choose the kind of account you need, then create your workspace. The same\n      sign-up covers every program.</p>\n\n    <form class=\"entry-form\" data-auth=\"setup\" novalidate autocomplete=\"off\">\n      <div class=\"entry-err\" data-err=\"_general\" role=\"alert\" hidden></div>\n\n      <!-- Directive 2 Oct 2026, Part 5.9: the setup code, above every other field. The\n           server verifies it; a placeholder until the voucher and registration system. -->\n      <div class=\"entry-setup-code\">\n        <label class=\"entry-flabel\" for=\"setupCode\">Setup code</label>\n        <input id=\"setupCode\" class=\"entry-text-input\" type=\"text\" autocomplete=\"off\"\n          placeholder=\"The code you were given\" data-field=\"setup_code\" />\n        <div class=\"entry-field-err\" data-err=\"setup_code\" role=\"alert\"></div>\n      </div>\n\n      <!-- The one question the address used to answer. Neither option is\n           pre-selected: an account created in the wrong space cannot be moved\n           into the other one, and a default that nobody looked at is exactly\n           how that happens. auth.js reveals the Organization field, rewrites\n           the title and fills the note below as this changes. -->\n      <fieldset class=\"entry-roles entry-roles-row\" data-slot=\"role-picker\">\n        <legend class=\"entry-flabel\">What are you signing up for?</legend>\n\n        <label class=\"entry-role\">\n          <input type=\"radio\" name=\"setupAccountType\" value=\"enterprise\" data-field=\"account_type\" />\n          <span>\n            <span class=\"entry-role-name\">Enterprise</span>\n            <span class=\"entry-role-sub\">A team runs the programs together, in one shared workspace you\n              administer.</span>\n          </span>\n        </label>\n\n        <label class=\"entry-role\">\n          <input type=\"radio\" name=\"setupAccountType\" value=\"leader\" data-field=\"account_type\" />\n          <span>\n            <span class=\"entry-role-name\">Leaders</span>\n            <span class=\"entry-role-sub\">One person, one workspace. Everything you do in it is yours alone.</span>\n          </span>\n        </label>\n\n        <div class=\"entry-field-err\" data-err=\"account_type\" role=\"alert\"></div>\n      </fieldset>\n\n      <!-- Two columns. Each field keeps label → input → error slot together in\n           one cell so a message never pushes the neighbouring column around. -->\n      <div class=\"entry-grid\">\n        <!-- Enterprise only — hidden (and not sent) for a Leader account, and\n             hidden until the choice above is made. -->\n        <div class=\"entry-cell\" data-slot=\"org-field\">\n          <label class=\"entry-flabel\" for=\"setupOrg\">Organization name</label>\n          <input id=\"setupOrg\" class=\"entry-text-input\" type=\"text\" autocomplete=\"organization\"\n            placeholder=\"e.g. Acme Manufacturing\" data-field=\"organization_name\" />\n          <div class=\"entry-field-err\" data-err=\"organization_name\" role=\"alert\"></div>\n        </div>\n\n        <div class=\"entry-cell\">\n          <label class=\"entry-flabel\" for=\"setupName\">Your name</label>\n          <input id=\"setupName\" class=\"entry-text-input\" type=\"text\" autocomplete=\"name\" placeholder=\"e.g. Maria Torres\"\n            data-field=\"name\" />\n          <div class=\"entry-field-err\" data-err=\"name\" role=\"alert\"></div>\n        </div>\n\n        <div class=\"entry-cell\">\n          <label class=\"entry-flabel\" for=\"setupEmail\">Email</label>\n          <input id=\"setupEmail\" class=\"entry-text-input\" type=\"email\" autocomplete=\"email\"\n            placeholder=\"e.g. maria@acme.com\" data-field=\"email\" />\n          <div class=\"entry-field-err\" data-err=\"email\" role=\"alert\"></div>\n        </div>\n\n        <div class=\"entry-cell\">\n          <label class=\"entry-flabel\" for=\"setupUser\">Username</label>\n          <input id=\"setupUser\" class=\"entry-text-input\" type=\"text\" autocomplete=\"username\" placeholder=\"e.g. maria\"\n            data-field=\"username\" />\n          <div class=\"entry-field-err\" data-err=\"username\" role=\"alert\"></div>\n        </div>\n\n        <!-- Directive 2 Oct 2026, Part 5.9: the first person's own password, typed twice\n             (the setup code is the first field of the form, above). -->\n        <div class=\"entry-cell\">\n          <label class=\"entry-flabel\" for=\"setupPassword\">Password</label>\n          <input id=\"setupPassword\" class=\"entry-text-input\" type=\"password\"\n            autocomplete=\"new-password\" placeholder=\"Choose a password\" data-field=\"password\" />\n          <div class=\"entry-field-err\" data-err=\"password\" role=\"alert\"></div>\n          <div class=\"pw-rule\">At least 8 characters, including a number and a special character such as ! or #.</div>\n        </div>\n\n        <div class=\"entry-cell\">\n          <label class=\"entry-flabel\" for=\"setupConfirm\">Confirm password</label>\n          <input id=\"setupConfirm\" class=\"entry-text-input\" type=\"password\"\n            autocomplete=\"new-password\" placeholder=\"Type it again\" data-field=\"confirm\" />\n          <div class=\"entry-field-err\" data-err=\"confirm\" role=\"alert\"></div>\n        </div>\n\n        <div class=\"entry-cell entry-cell-end\">\n          <label class=\"entry-remember\">\n            <input type=\"checkbox\" id=\"setupRemember\" /> <span>Remember me on this device</span>\n          </label>\n        </div>\n      </div>\n\n      <!-- Which programs this account starts with, stated rather than asked:\n           the whole of whichever space was chosen above. Filled in by auth.js\n           once there is a choice to describe. -->\n      <p class=\"entry-note\" data-slot=\"program-note\" hidden></p>\n\n      <button type=\"submit\" class=\"btn-gold login-btn\" data-submit>Create &amp; Continue &rarr;</button>\n    </form>\n  </div>\n</div>\n",
  "admin-login": "<!-- ─────────────────────────────────────────────────────────────\n     admin-login.html — the administrator's sign-in (markup only)\n     Hydrated by auth.js → Entry.mount('admin-login', …). A username and a\n     password (Directive 2 Oct 2026, Part 5.12): the account exists from\n     installation, so there is no first-use screen.\n\n     This is the ONE entry screen with no program behind it — the console\n     reaches across every organization — so it keeps the root address\n     /apps/admin, and its way out is the launchpad rather than any one\n     program's sign-in. Every other door belongs to a program.\n     ───────────────────────────────────────────────────────────── -->\n<div class=\"login-screen\"><div class=\"login-card entry-pass-card\">\n  <button type=\"button\" class=\"entry-back\" data-go=\"launchpad\">&larr; All programs</button>\n  <div class=\"login-eyebrow\">Administrator</div>\n  <h1 class=\"login-title\" data-slot=\"title\">Admin <em>sign in</em></h1>\n  <p class=\"login-sub\" data-slot=\"sub\">Enter the administrator username and password to view all organizations and users.</p>\n\n  <form class=\"entry-form\" data-auth=\"admin\" novalidate autocomplete=\"off\">\n    <input id=\"adminUser\" class=\"entry-text-input\" type=\"text\" autocomplete=\"username\"\n           placeholder=\"Username\" data-field=\"user\" aria-label=\"Username\"/>\n    <div class=\"entry-field-err\" data-err=\"user\" role=\"alert\"></div>\n\n    <input id=\"adminPassword\" class=\"entry-text-input\" type=\"password\" autocomplete=\"current-password\"\n           placeholder=\"Password\" data-field=\"password\" aria-label=\"Password\"/>\n    <div class=\"entry-field-err\" data-err=\"password\" role=\"alert\"></div>\n\n    <div class=\"entry-err\" data-err=\"_general\" role=\"alert\" hidden></div>\n\n    <button type=\"submit\" class=\"btn-gold login-btn\" data-slot=\"submit\" data-submit>Enter &rarr;</button>\n  </form>\n</div></div>\n",
  "choose-password": "<!-- ─────────────────────────────────────────────────────────────\n     choose-password.html — Choose a new password (markup only)\n     Directive 2 Oct 2026, Part 5.5. Shown after a sign-in with a temporary\n     password, the administrator's first sign-in (the published password works\n     once), or a stored password that breaks the rule (an old PIN). The server\n     refuses everything else until it is done. Hydrated by auth.js →\n     Entry.mount('choose-password', …); the sub-text says which case this is.\n     ───────────────────────────────────────────────────────────── -->\n<div class=\"login-screen\"><div class=\"login-card entry-pass-card\">\n  <button type=\"button\" class=\"entry-back\" data-leave>&larr; Back to sign in</button>\n  <div class=\"login-eyebrow\" data-slot=\"module-name\">90-Day Programs</div>\n  <h1 class=\"login-title\">Choose a new <em>password</em></h1>\n  <p class=\"login-sub\" data-slot=\"sub\"></p>\n\n  <form class=\"entry-form\" data-auth=\"choose-password\" novalidate autocomplete=\"off\">\n    <label class=\"entry-flabel\" for=\"newPassword\">New password</label>\n    <input id=\"newPassword\" class=\"entry-text-input\" type=\"password\" autocomplete=\"new-password\"\n           data-field=\"password\" aria-describedby=\"newPasswordRule\"/>\n    <div class=\"entry-field-err\" data-err=\"password\" role=\"alert\"></div>\n    <div class=\"pw-rule\" id=\"newPasswordRule\">At least 8 characters, including a number and a special character such as ! or #.</div>\n\n    <label class=\"entry-flabel\" for=\"confirmPassword\">Confirm new password</label>\n    <input id=\"confirmPassword\" class=\"entry-text-input\" type=\"password\" autocomplete=\"new-password\"\n           data-field=\"confirm\"/>\n    <div class=\"entry-field-err\" data-err=\"confirm\" role=\"alert\"></div>\n\n    <div class=\"entry-err\" data-err=\"_general\" role=\"alert\" hidden></div>\n\n    <button type=\"submit\" class=\"btn-gold login-btn\" data-submit>Save password</button>\n  </form>\n</div></div>\n",
  "nav": "<!-- ─────────────────────────────────────────────────────────────\n     nav.html — Top navigation bar (markup only; no inline JS)\n     Two regions, injected by nav.js into the persistent containers\n     #navTabs and #navRight (see index.html). Dynamic bits — active\n     tab, badges, theme label, the user chip and the More menu — are\n     filled in nav.js. All clicks are handled by one delegated listener\n     on <nav> via data-tab / data-act.\n     ───────────────────────────────────────────────────────────── -->\n<div data-region=\"tabs\">\n  <button class=\"nav-tab\" data-tab=\"home\">Home</button>\n  <button class=\"nav-tab\" data-tab=\"learn\">Learn</button>\n  <button class=\"nav-tab\" data-tab=\"pipeline\">Pipeline</button>\n  <button class=\"nav-tab\" data-tab=\"phase5\">Navigate</button>\n  <button class=\"nav-tab\" data-tab=\"insights\">Insights</button>\n</div>\n\n<div data-region=\"right\">\n  <span class=\"nav-module-wrap\">\n    <button class=\"nav-module-btn\" data-act=\"modules\" aria-haspopup=\"true\" aria-expanded=\"false\" title=\"Switch module\">\n      <span class=\"nav-module-eyebrow\">Module</span>\n      <span class=\"nav-module-name\" data-slot=\"module-name\">&nbsp;</span>\n      <span class=\"nav-module-caret\" aria-hidden=\"true\">&#9662;</span>\n    </button>\n    <span data-slot=\"module-menu\"></span>\n  </span>\n  <span data-slot=\"userchip\"></span>\n  <button class=\"btn-ghost pad-chip-md nav-action\" data-act=\"help\" title=\"Help\">? Help</button>\n  <button class=\"btn-ghost pad-chip-md nav-action\" data-act=\"theme\" title=\"Switch theme\">&#9680; <span data-slot=\"theme-label\">Dark Mode</span></button>\n  <button id=\"gchatNavBtn\" class=\"btn-ghost pad-chip-md nav-action\" data-act=\"gchat\">&#8801; Team Chat<span id=\"gchatUnread\" class=\"gchat-unread\" style=\"display:none\">0</span></button>\n  <button id=\"notesNavBtn\" class=\"btn-ghost pad-chip-md nav-action\" data-act=\"notes\">&#9998; Notes<span id=\"notesCount\" class=\"notes-count\" style=\"display:none\">0</span></button>\n  <!-- Directive 2 Oct 2026, Part 3: the AI Innovation Pipeline shows Demo in Notes' place (nav.js hydrateRight). -->\n  <button id=\"sampleNavBtn\" class=\"btn-ghost pad-chip-md nav-action\" data-act=\"demo\" style=\"display:none\">&#9673; Demo</button>\n  <!-- Phone/tablet only (see the responsive header block in styles.css):\n       opens the drawer that carries everything else in this region. -->\n  <button class=\"nav-drawer-btn\" data-act=\"drawer\" aria-haspopup=\"dialog\" aria-expanded=\"false\"\n          aria-controls=\"navDrawer\" title=\"Menu\" aria-label=\"Menu\">&#9776;</button>\n  <span class=\"nav-more-wrap\">\n    <button class=\"btn-ghost pad-chip-md nav-action\" data-act=\"more\" aria-haspopup=\"true\" aria-expanded=\"false\" title=\"More\">&#8943; <span class=\"nav-action-label\">More</span></button>\n    <span data-slot=\"more-menu\"></span>\n  </span>\n</div>\n",
};
